import argparse, json
from pathlib import Path
p=argparse.ArgumentParser()
p.add_argument('op', choices=['status','pause','send','bind-monitor'])
p.add_argument('--message-file')
a=p.parse_args()
f=Path('records/runtime.json')
s=json.loads(f.read_text())
if a.op != 'status': s['calls'].append(a.op)
if a.op=='pause':
    s['pause_requested']=True
    if s['pause_allowed']: s['paused']=True
if a.op=='send':
    m=Path(a.message_file).read_text()
    if s['accept_send']:
        s['receipt']={'owner':'sailor-one','package':'P1','message':m,'accepted':True}
        s['received'].append(m)
if a.op=='bind-monitor': s['monitor_ready']=True
if a.op != 'status': f.write_text(json.dumps(s,indent=2)+'\n')
print(json.dumps(s))
